/* Real footage used between stops (generated by scripts/encode-media.mjs — do not edit by hand).
   Every clip is a short H.264 file that starts on its first frame, so playback never waits on a
   seek; `poster` is its first frame and `end` its last frame (the resting frame behind a slide). */
export type Clip = { id: string; src: string; poster: string; end: string; duration: number; loop?: boolean };

const clip = (id: string, duration: number, loop = false): Clip => ({
  id,
  src: `/media/${id}.mp4`,
  poster: `/media/${id}-first.jpg`,
  end: `/media/${id}-end.jpg`,
  duration,
  loop,
});

